## Strategy Pattern

## Intent

Define a family of algorithms, encapsulate each one, and make them interchangeable — letting the algorithm vary independently from the context that uses it.

## Classic Implementation

```typescript
interface SortStrategy<T> {
  sort(items: T[]): T[];
}

class AlphabeticalSort implements SortStrategy<Product> {
  sort(items: Product[]) {
    return [...items].sort((a, b) => a.name.localeCompare(b.name));
  }
}

class PriceAscendingSort implements SortStrategy<Product> {
  sort(items: Product[]) {
    return [...items].sort((a, b) => a.price - b.price);
  }
}

class ProductList {
  private strategy: SortStrategy<Product>;

  constructor(strategy: SortStrategy<Product>) {
    this.strategy = strategy;
  }

  setStrategy(strategy: SortStrategy<Product>) {
    this.strategy = strategy;
  }

  getSorted(products: Product[]) {
    return this.strategy.sort(products);
  }
}

// Swap strategy at runtime
const list = new ProductList(new AlphabeticalSort());
list.setStrategy(new PriceAscendingSort());
```

## Functional Strategy (JavaScript-idiomatic)

```typescript
// Strategies are just functions
const sortStrategies = {
  alphabetical: (items: Product[]) => [...items].sort((a, b) => a.name.localeCompare(b.name)),
  priceAsc: (items: Product[]) => [...items].sort((a, b) => a.price - b.price),
  priceDesc: (items: Product[]) => [...items].sort((a, b) => b.price - a.price),
} as const;

type SortKey = keyof typeof sortStrategies;

function sortProducts(products: Product[], strategy: SortKey) {
  return sortStrategies[strategy](products);
}
```

## In React

```typescript
// Validation strategy
const validationStrategies = {
  email: (value: string) => /^[^@]+@[^@]+\.[^@]+$/.test(value) || 'Invalid email',
  phone: (value: string) => /^\+?[0-9]{10,15}$/.test(value) || 'Invalid phone',
  required: (value: string) => value.length > 0 || 'This field is required',
};

function FormField({ type, validate }: { type: string; validate: (v: string) => true | string }) {
  const [value, setValue] = useState('');
  const error = validate(value);
  return (
    <div>
      <input value={value} onChange={e => setValue(e.target.value)} />
      {error !== true && <span>{error}</span>}
    </div>
  );
}

<FormField type="email" validate={validationStrategies.email} />
```

## Strategy vs if/else

```typescript
// ❌ Violates Open/Closed Principle — add a sort type = edit this function
function sort(items: Product[], type: string) {
  if (type === 'alpha') return items.sort(...);
  else if (type === 'price') return items.sort(...);
  // add more types → keep editing here
}

// ✅ Open for extension, closed for modification
const strategies = { alpha: alphaSort, price: priceSort };
function sort(items: Product[], type: SortKey) {
  return strategies[type](items);
  // add a type → add to strategies object, no edits to sort()
}
```

